class Confirmation(object):

    def __init__(self, command, confirmation_code, confirmation_text, confirmation_msg=""):
        """
        Generic class for all TMA confirmations

        :param command:
        :param confirmation_code:
        :param confirmation_text:
        :param confirmation_msg:
        """
        self.command = command
        self.confirmation_code = confirmation_code
        self.confirmation_text = confirmation_text
        self.confirmation_msg = confirmation_msg

    @classmethod
    def from_string(cls, confirmation_string):
        """
        General command output parser

        :param confirmation_string:
        :return:Confirmation object containing command,confirmation_code,confirmation_text,confirmation_msg

        EX: p = Confirmation.from_string(command_output)
            print(p.command, p.confirmation_code, p.confirmation_text, p.confirmation_msg)
        """
        output = confirmation_string.split(" ", 4)
        if len(output) < 4:
            raise ValueError("Invalid Input")
        else:
            return Confirmation(output[1].strip(), output[2].strip(), output[3].strip(),
                                output[4].strip() if len(output) == 5 else "")


class GETRConfirmation(Confirmation):

    def __init__(self, command, confirmation_code, confirmation_text, confirmation_msg, radio_cards):
        """
        GETR Command confirmation

        :param command:
        :param confirmation_code:
        :param confirmation_text:
        :param confirmation_msg:
        :param radio_cards:
        """
        super(GETRConfirmation, self).__init__(command, confirmation_code, confirmation_text, confirmation_msg)
        self.radio_cards = radio_cards

    @classmethod
    def from_string(cls, confirmation_string):
        """
        Parse GETR CommandOutput

        :param confirmation_string:
        :return: Confirmation object contains command,confirmation_code,confirmation_text,confirmation_msg,radio_cards

        Ex: for item in GETRConfirmation.from_string(command_output).radio_cards:
                print ( "Card:",item.Card)
                print ("Chasis:",item.Chassis )
                print ("Context:",item.Context)
                print( "RF:",item.RF )
                print ("DL:",item.A.DL )
                print("UL:",item.A.UL)
                print("===================")
        In case if Confirmation text is not "OK"
            GETRConfirmation.from_string(command_output).radio_cards is equal to the Confirmation message
        """

        res = Confirmation.from_string(confirmation_string)
        if res.confirmation_text == "Ok":
            message_txt = res.confirmation_msg.split("==============")
            radio_cards_list = []
            for item in message_txt:
                if ":" in item:
                    radio_cards_list.append(RadioCard.from_string(item))
            return GETRConfirmation(res.command, res.confirmation_code, res.confirmation_text,
                                    res.confirmation_msg, radio_cards_list)
        else:
            return GETRConfirmation(res.command, res.confirmation_code, res.confirmation_text,
                                    res.confirmation_msg, res.confirmation_msg)


class Frequency(object):
    def __init__(self, dl, ul):
        """
        :param dl:
        :param ul:
        """
        self.dl = dl
        self.ul = ul


class RadioCard(object):
    def __init__(self, card="", slot="", chassis="", context="", load="", rf="", dl="", ul=""):
        """

        :param card:
        :param slot:
        :param chassis:
        :param context:
        :param load:
        :param rf:
        :param dl:
        :param ul:
        """
        self.card = card
        self.slot = slot
        self.chassis = chassis
        self.context = context
        self.load = load
        self.rf = rf
        self.pointA = Frequency(dl, ul)

    @classmethod
    def from_string(cls, item):
        """
        :param item:
        :return: RadioCard Object
        """
        frequency_attr = None
        radio_card_dict = {}
        for row in item.split("\n"):
            if ': ' in row:
                key, value = row.split(": ", 1)
                if key.strip().startswith("A"):
                    frequency_attr = key.strip()
                    if ':' in value:
                        link, freq_range = value.split(":")
                        radio_card_dict["dl"] = freq_range.strip()
                elif frequency_attr == 'A':
                    radio_card_dict["ul"] = value.strip()
                else:
                    radio_card_dict[key.strip().replace("*", "").lower().strip()] = value.strip()
        return RadioCard(radio_card_dict["card"], radio_card_dict["slot"], radio_card_dict["chassis"],
                         radio_card_dict["context"], radio_card_dict["load"] if "load" in radio_card_dict else "",
                         radio_card_dict["rf"],
                         radio_card_dict["dl"], radio_card_dict["ul"])


class Version:
    def __init__(self, hardware, version):
        """

        :param hardware:
        :param version:
        """
        self.hardware = hardware
        self.version = version


class GVERConfirmation(Confirmation):

    def __init__(self, command, confirmation_code, confirmation_text, confirmation_msg, version):
        """
        GVER Command Confirmation

        :param command:
        :param confirmation_code:
        :param confirmation_text:
        :param confirmation_msg:
        """
        super(GVERConfirmation, self).__init__(command, confirmation_code, confirmation_text, confirmation_msg)
        self.version = version

    @classmethod
    def from_string(cls, confirmation_string):
        """
        Parse GVER CommandOutput

        :param confirmation_string:

        :return: Confirmation object contains command,confirmation_code,confirmation_text,confirmation_msg,version

        Ex: for item in GVERConfirmation.from_string(command_output).version:
                print(item.hardware, ":", item.version)
        sample output:
                    PPC-0 : NLA4.19.0 NG160820191 Rev1
                    DSP-0 : NLA4.19.0 NG160820191 Rev1 (Nx2)
                    DSP-1 : NLA4.19.0 NG160820191 Rev1 (Nx2)
                    DSP-2 : NLA4.19.0 NG160820191 Rev1 (Nx2)
                    DSP-3 : NLA4.19.0 NG160820191 Rev1 (Nx2)
                    DSP-4 : NLA4.19.0 NG160820191 Rev1 (Nx2)
                    DSP-5 : NLA4.19.0 NG160820191 Rev1 (Nx2)

        """
        res = Confirmation.from_string(confirmation_string)
        version_txt = res.confirmation_msg
        if res.confirmation_text == "Ok":
            hardware_version_details = []
            for item in version_txt.split("\n"):
                if item.strip().endswith(":"):
                    key = item.strip().replace(":", "")
                else:
                    if item.__contains__("VERSION:"):
                        hardware_version_details.append(Version(key, item.strip().split("VERSION:", 1)[1].strip()))
            return GVERConfirmation(res.command, res.confirmation_code, res.confirmation_text, res.confirmation_msg,
                                    hardware_version_details)
        else:
            return GVERConfirmation(res.command, res.confirmation_code, res.confirmation_text,
                                    res.confirmation_msg, res.confirmation_msg)
